def cluster_rows(raw_rows, thr=0.9):
    """Single-linkage cluster on |cosine|. Returns one averaged row per cluster."""
    R = np.array([r / np.linalg.norm(r) for r in raw_rows])
    n = len(R)
    sims = np.abs(R @ R.T)
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[ra] = rb
    for i in range(n):
        for j in range(i + 1, n):
